const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox', '--disable-setuid-sandbox'] });
  const page = await browser.newPage();

  // Set viewport to poster dimensions (portrait)
  await page.setViewportSize({ width: 900, height: 1400 });

  const htmlPath = path.resolve('/app/output/hunger-crisis-poster-infographic.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle', timeout: 30000 });

  // Wait for fonts and rendering
  await page.waitForTimeout(4000);

  // Re-render to ensure fonts are loaded
  await page.evaluate(() => {
    if (window._infographic && window._syntax) {
      window._infographic.render(window._syntax);
    }
  });

  await page.waitForTimeout(3000);

  // Take screenshot
  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: false,
    clip: { x: 0, y: 0, width: 900, height: 1400 },
  });

  console.log('Screenshot saved to /app/output/final_poster.png');
  await browser.close();
})();

