from playwright.sync_api import sync_playwright

with sync_playwright() as p:
    browser = p.chromium.launch(args=['--no-sandbox', '--disable-setuid-sandbox'])
    page = browser.new_page()
    page.set_viewport_size({"width": 900, "height": 1400})

    html_path = '/app/output/hunger-crisis-poster-infographic.html'
    page.goto(f'file://{html_path}', wait_until='networkidle', timeout=30000)
    page.wait_for_timeout(4000)
    page.evaluate("""() => {
        if (window._infographic && window._syntax) {
            window._infographic.render(window._syntax);
        }
    }""")
    page.wait_for_timeout(3000)

    # Check actual canvas/svg dimensions
    dims = page.evaluate("""() => {
        const container = document.getElementById('container');
        const svg = container.querySelector('svg');
        const canvas = container.querySelector('canvas');
        const el = svg || canvas || container;
        const rect = el.getBoundingClientRect();
        return {
            containerW: container.offsetWidth,
            containerH: container.offsetHeight,
            elW: rect.width,
            elH: rect.height,
            elTop: rect.top,
            elLeft: rect.left,
            svgWidth: svg ? svg.getAttribute('width') : null,
            svgHeight: svg ? svg.getAttribute('height') : null,
            bodyScrollH: document.body.scrollHeight,
        };
    }""")
    print(dims)

    browser.close()

