from playwright.sync_api import sync_playwright

with sync_playwright() as p:
    browser = p.chromium.launch(args=['--no-sandbox', '--disable-setuid-sandbox'])
    page = browser.new_page()
    page.set_viewport_size({"width": 900, "height": 1400})

    html_path = '/app/output/hunger-crisis-poster-infographic.html'
    page.goto(f'file://{html_path}', wait_until='networkidle', timeout=30000)
    page.wait_for_timeout(5000)
    page.evaluate("""() => {
        if (window._infographic && window._syntax) {
            window._infographic.render(window._syntax);
        }
    }""")
    page.wait_for_timeout(3000)

    # Get the SVG bounding box of actual content
    bounds = page.evaluate("""() => {
        const svg = document.querySelector('#container svg');
        if (!svg) return null;
        const bbox = svg.getBBox();
        // Also check all child elements
        const children = svg.querySelectorAll('g, rect, text, path');
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
        children.forEach(el => {
            try {
                const b = el.getBBox();
                if (b.width > 0 && b.height > 0) {
                    minX = Math.min(minX, b.x);
                    minY = Math.min(minY, b.y);
                    maxX = Math.max(maxX, b.x + b.width);
                    maxY = Math.max(maxY, b.y + b.height);
                }
            } catch(e) {}
        });
        return { svgBBox: bbox, contentBounds: {minX, minY, maxX, maxY} };
    }""")
    print(bounds)
    browser.close()

