from playwright.sync_api import sync_playwright

with sync_playwright() as p:
    browser = p.chromium.launch(args=['--no-sandbox', '--disable-setuid-sandbox'])
    page = browser.new_page()
    page.set_viewport_size({"width": 800, "height": 1200})

    html_path = '/app/output/hunger-crisis-poster-infographic.html'
    page.goto(f'file://{html_path}', wait_until='networkidle', timeout=30000)
    page.wait_for_timeout(4000)
    page.evaluate("""() => {
        if (window._infographic && window._syntax) {
            window._infographic.render(window._syntax);
        }
    }""")
    page.wait_for_timeout(3000)
    page.evaluate("document.getElementById('export-btn').style.display='none'")

    # Get content bounds
    bounds = page.evaluate("""() => {
        const svg = document.querySelector('#container svg');
        const groups = svg.querySelectorAll('g');
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
        groups.forEach(g => {
            try {
                const rect = g.getBoundingClientRect();
                if (rect.width > 10 && rect.height > 10) {
                    minX = Math.min(minX, rect.left);
                    minY = Math.min(minY, rect.top);
                    maxX = Math.max(maxX, rect.right);
                    maxY = Math.max(maxY, rect.bottom);
                }
            } catch(e) {}
        });
        return { minX, minY, maxX, maxY, w: maxX-minX, h: maxY-minY };
    }""")
    print('Content bounds:', bounds)

    # Crop to content with small padding
    pad = 20
    x = max(0, int(bounds['minX']) - pad)
    y = max(0, int(bounds['minY']) - pad)
    w = int(bounds['maxX']) - x + pad
    h = int(bounds['maxY']) - y + pad

    page.screenshot(
        path='/app/output/final_poster.png',
        clip={'x': x, 'y': y, 'width': w, 'height': h}
    )
    print(f'Saved {w}x{h} crop')
    browser.close()

