<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Hunger Doesn't Wait — Together We Can End It - Infographic</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body { width: 800px; height: 1200px; overflow: hidden; background: #1a0a00; }
    #container { width: 800px; height: 1200px; }
    #export-btn {
      position: fixed; top: 10px; right: 10px; z-index: 999;
      padding: 8px 16px; background: #ea580c; color: white;
      border: none; border-radius: 6px; cursor: pointer; font-size: 14px;
    }
  </style>
</head>
<body>
  <button id="export-btn" onclick="exportSVG()">Export SVG</button>
  <div id="container"></div>
  <script src="/app/vendor/infographic.min.js"></script>
  <script>
    const syntax = `infographic list-waterfall-badge-card
data
  title Hunger Doesn't Wait — Together We Can End It
  desc 48 million Americans face hunger every day — including 14 million children. A united network of food banks is fighting back. You can help now.
  lists
    - label 48 Million Americans Face Hunger
      value 48
      desc Across every state — including 14 million children
      icon person 2 fill
    - label 5.7 Billion Meals Distributed
      value 5.7
      desc Delivered through 200+ food banks in our nationwide network
      icon fork knife
    - label 4.3 Billion Pounds Rescued
      value 4.3
      desc Good food saved from waste and redirected to families in need
      icon leaf fill
    - label $1 Provides 10 Meals
      value 1
      desc Your dollar goes further here — gifts are currently being matched
      icon heart fill
    - label Donate
      desc Give now to provide meals to neighbors facing hunger
      icon dollarsign circle fill
    - label Advocate
      desc Urge lawmakers to protect hunger-relief programs
      icon megaphone fill
    - label Fundraise
      desc Rally your community to give together
      icon person 3 fill
    - label Volunteer
      desc Sort, pack, and distribute food — your hands are needed
      icon hand raised fill
theme
  palette #ea580c #d97706 #dc2626 #b45309`;

    const infographic = new AntVInfographic.Infographic({
      container: '#container',
      width: 800,
      height: 1200,
    });

    infographic.render(syntax);

    document.fonts?.ready.then(() => {
      infographic.render(syntax);
    }).catch((error) => console.error('Error waiting for fonts to load:', error));

    async function exportSVG() {
      const svgDataUrl = await infographic.toDataURL({ type: 'svg' });
      const a = document.createElement('a');
      a.href = svgDataUrl;
      a.download = 'hunger-crisis-poster.svg';
      a.click();
    }

    window._infographic = infographic;
    window._syntax = syntax;
  </script>
</body>
</html>
